/**
 * Large-company setup: what in a rate card contradicts itself or is unfinished. Flagged for an admin to settle, never
 * guessed. Blocking ones stop publishing until they are fixed in the card or decided (decisions[] keyed by `key`). Pure.
 */
import type { RateCardDefinition, Service } from './rules.ts';
import { dollars, r2 } from './answers.ts';

export type ContradictionKind = 'day_vs_rate' | 'range_rule' | 'bands' | 'matrix' | 'min_max' | 'missing_question'
  | 'unpriced' | 'crew' | 'policy' | 'membership' | 'eligibility' | 'finding';

export interface Contradiction {
  key: string;
  kind: ContradictionKind;
  serviceKey?: string;
  message: string;
  blocking: boolean;
  /** Present when settling it is a decision rather than an edit. */
  choices?: { value: string; label: string }[];
  resolved: boolean;
  decision?: string;
}

function strategyQuestions(s: Service): string[] {
  const st = s.strategy;
  switch (st.kind) {
    case 'fixed': return [];
    case 'per_unit': return [st.unitQuestion];
    case 'threshold': return [st.question, st.quantityQuestion].filter(Boolean) as string[];
    case 'first_additional': return [st.unitQuestion];
    case 'measurement': return [st.question, st.quantityQuestion, ...(st.variants ?? []).flatMap((v) => [v.when.question, v.rateQuestion])].filter(Boolean) as string[];
    case 'time_block': return [st.minutesQuestion];
    case 'per_dbh': return [st.dbhQuestion, st.treesQuestion].filter(Boolean) as string[];
    case 'matrix': return [st.rowQuestion, st.colQuestion, st.quantityQuestion].filter(Boolean) as string[];
    case 'height': return [st.heightQuestion, st.quantityQuestion].filter(Boolean) as string[];
    case 'crew_time': return [st.crewQuestion, st.hoursQuestion, ...(st.equipmentAdders ?? []).map((e) => e.question)];
    case 'recurring_plan': return [st.classQuestion];
    case 'sub_bid': return [st.costQuestion];
    case 'manual': return [st.priceQuestion];
  }
}

function unpriced(def: RateCardDefinition, s: Service): string | null {
  const st = s.strategy;
  switch (st.kind) {
    case 'fixed': return st.price > 0 ? null : 'Set a price';
    case 'per_unit': return st.unitPrice > 0 ? null : 'Set a price per unit';
    case 'threshold': return st.bands.some((b) => b.price > 0) ? null : 'Set the band prices';
    case 'first_additional': return st.first > 0 ? null : 'Set the first-unit price';
    case 'measurement': return st.perUnit > 0 ? null : 'Set the price per unit';
    case 'time_block': return st.blockPrice > 0 ? null : 'Set the price per time block';
    case 'per_dbh': return st.perInch > 0 ? null : 'Set the price per DBH inch';
    case 'matrix': return Object.values(st.cells).some((v) => typeof v === 'number' && v > 0) ? null : 'Fill in the price table';
    case 'height': return st.perFoot > 0 ? null : 'Set the price per foot';
    case 'crew_time':
      if (def.pricing.method === 'cost_plus') return def.pricing.targetMargin !== undefined ? null : 'Set the target return';
      return def.pricing.manHourRate || def.crews.some((c) => c.manHourRate) ? null : 'Set the man-hour rate';
    case 'recurring_plan': return null;
    case 'sub_bid': return null;
    case 'manual': return null;
  }
}

export function findContradictions(def: RateCardDefinition): Contradiction[] {
  const out: Contradiction[] = [];
  const decided = new Map(def.decisions.map((d) => [d.key, d.choice]));
  const push = (c: Omit<Contradiction, 'resolved' | 'decision'>) => {
    const choice = decided.get(c.key);
    out.push({ ...c, resolved: c.choices ? choice !== undefined : false, decision: choice });
  };

  for (const s of def.services) {
    // A switched-off service is never priced (isOffered refuses it), so nothing about it can be open. A company
    // that doesn't sell memberships must not be asked to price one before it can publish.
    if (s.offered === false) continue;
    const st = s.strategy;
    const qs = new Set(s.questions.map((q) => q.key));
    for (const k of strategyQuestions(s)) {
      if (!qs.has(k)) push({ key: `question:${s.key}:${k}`, kind: 'missing_question', serviceKey: s.key, blocking: true, message: `${s.name}: the price uses "${k}", but there's no such question.` });
    }
    const u = unpriced(def, s);
    if (u) push({ key: `unpriced:${s.key}`, kind: 'unpriced', serviceKey: s.key, blocking: true, message: `${s.name}: ${u}.` });
    if (s.minimum !== undefined && s.maximum !== undefined && s.minimum > s.maximum) {
      push({ key: `min_max:${s.key}`, kind: 'min_max', serviceKey: s.key, blocking: true, message: `${s.name}: the minimum ${dollars(s.minimum)} is above the maximum ${dollars(s.maximum)}.` });
    }
    if (st.kind === 'crew_time') {
      const choice = s.questions.find((q) => q.key === st.crewQuestion);
      for (const c of choice?.choices ?? []) {
        if (!def.crews.some((t) => t.key === c.value)) push({ key: `crew:${s.key}:${c.value}`, kind: 'crew', serviceKey: s.key, blocking: true, message: `${s.name}: the crew "${c.label}" isn't set up.` });
      }
      const rate = def.pricing.manHourRate;
      if (def.pricing.method === 'man_hour' && rate) {
        for (const f of st.floors ?? []) {
          if (!f.headcount) continue;
          const byRate = f.headcount * f.minHours * rate;
          if (Math.abs(byRate - f.price) < 0.5) continue;
          const implied = r2(f.price / (f.headcount * rate));
          push({
            key: `day_vs_rate:${s.key}:${f.key}`, kind: 'day_vs_rate', serviceKey: s.key, blocking: true,
            message: `${s.name}: a ${f.headcount}-person day of ${f.minHours} hours is ${dollars(f.price)}, but ${f.headcount} × ${f.minHours} hours × ${dollars(rate)} is ${dollars(byRate)}. They only agree at ${implied}-hour days. Which rule controls?`,
            choices: [
              { value: 'rate', label: 'The man-hour rate' },
              { value: 'day_price', label: 'The day price' },
              { value: 'floor', label: 'The day price as a floor' },
            ],
          });
        }
      }
    }
    if (st.kind === 'measurement') {
      (st.variants ?? []).forEach((v, i) => {
        if (v.range && v.range.rule === null) {
          push({ key: `range:${s.key}:${i}`, kind: 'range_rule', serviceKey: s.key, blocking: true, message: `${s.name}: ${dollars(v.range.low)} to ${dollars(v.range.high)} is a range. Automation needs a rule: low, high, the middle, or the salesperson chooses.` });
        }
      });
    }
    if (st.kind === 'threshold') {
      const ups = st.bands.map((b) => b.upTo);
      const nums = ups.filter((u): u is number => u !== null);
      if (!ups.includes(null)) push({ key: `bands:${s.key}`, kind: 'bands', serviceKey: s.key, blocking: true, message: `${s.name}: no price above ${Math.max(...nums)}.` });
      if (new Set(nums).size !== nums.length || ups.filter((u) => u === null).length > 1) push({ key: `bands_overlap:${s.key}`, kind: 'bands', serviceKey: s.key, blocking: true, message: `${s.name}: two price bands overlap.` });
    }
    if (st.kind === 'matrix') {
      const missing: string[] = [];
      for (const r of st.rows) {
        if (st.cols && st.cols.length) { for (const c of st.cols) if (!(`${r.value}|${c.value}` in st.cells)) missing.push(`${r.label}, ${c.label}`); }
        else if (!(r.value in st.cells)) missing.push(r.label);
      }
      if (missing.length) push({ key: `matrix:${s.key}`, kind: 'matrix', serviceKey: s.key, blocking: true, message: `${s.name}: no price for ${missing.slice(0, 4).join('; ')}${missing.length > 4 ? ` and ${missing.length - 4} more` : ''}. Mark it "not offered" if you don't sell it.` });
    }
    if (st.kind === 'recurring_plan') {
      for (const c of st.classes) {
        if (c.initial === 0 && c.monthly === 0) push({ key: `membership:${s.key}:${c.value}`, kind: 'membership', serviceKey: s.key, blocking: true, message: `${s.name}: map the initial and monthly payments for "${c.label}".` });
      }
    }
  }

  const discounts = def.policies.discounts;
  const cats = new Map<string, number[]>();
  for (const d of discounts) for (const c of d.categories ?? []) cats.set(c, [...(cats.get(c) ?? []), d.percent]);
  for (const [cat, pcts] of cats) {
    if (new Set(pcts).size > 1) push({ key: `policy:discount:${cat}`, kind: 'policy', blocking: true, message: `Two discounts for "${cat}" give different amounts (${pcts.join('% and ')}%). Which is current?`, choices: discounts.filter((d) => d.categories?.includes(cat)).map((d) => ({ value: d.key, label: `${d.label} (${d.percent}%)` })) });
  }
  if (discounts.filter((d) => d.isDefault).length > 1) push({ key: 'policy:discount_default', kind: 'policy', blocking: true, message: 'Two discounts are marked as the default. Keep one.' });
  const plans = def.policies.paymentPlans;
  if (plans.filter((p) => p.isDefault).length > 1) {
    push({ key: 'policy:payment_plan', kind: 'policy', blocking: true, message: `Two payment plans are marked as the default (${plans.filter((p) => p.isDefault).map((p) => p.label).join(' and ')}). Which is current?`, choices: plans.filter((p) => p.isDefault).map((p) => ({ value: p.key, label: p.label })) });
  }

  const offered = new Set(def.services.filter((s) => s.offered !== false).map((s) => s.key));
  for (const r of def.playbooks) {
    if (r.when.service && !offered.has(r.when.service)) push({ key: `eligibility:${r.key}`, kind: 'eligibility', blocking: false, message: `The playbook "${r.name}" is for a service that isn't offered.` });
  }

  for (const f of def.findings) {
    push({ key: f.key, kind: 'finding', blocking: f.blocking, message: f.quote ? `${f.text} ("${f.quote}")` : f.text, choices: (f.choices ?? ['Settled']).map((c) => ({ value: c, label: c })) });
  }
  return out;
}

/** What still stops publishing. */
export const publishBlockers = (def: RateCardDefinition) => findContradictions(def).filter((c) => c.blocking && !c.resolved);
